const D = { energy: .6, scale: 1, speed: 1, density: .5, thick: .5, grain: .4, hue: 210, x: .5, y: .5, style: 'T1', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---------------------------------------------------------------------------
// MRI slice sweep -- an axial magnetic-resonance study scrolling head-first
// through a procedural cranial volume. Skull is dark cortical bone, scalp/fat a
// bright rind, subarachnoid CSF a thin moat, the brain a folded grey-matter
// ribbon over brighter white matter, and the lateral ventricles a central
// butterfly. The scan plane travels continuously up and down the volume so the
// cross-section is never the same twice. Windowed as T1 (white bright, CSF
// black), T2 (CSF blazing), FLAIR (CSF nulled, lesions hot) or a BOLD fMRI
// activation overlay in false colour.
// ---------------------------------------------------------------------------
const sd = P.seed | 0;
function hh(ix, iy) {
  let h = (Math.imul(ix, 374761393) + Math.imul(iy, 668265263) + Math.imul(sd + 1, 1442695041)) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177) | 0;
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;
}
function sstep(t) { return t * t * (3 - 2 * t); }
function vnoise(x, y) {
  const xi = Math.floor(x), yi = Math.floor(y);
  const xf = sstep(x - xi), yf = sstep(y - yi);
  const a = hh(xi, yi), b = hh(xi + 1, yi), c = hh(xi, yi + 1), d = hh(xi + 1, yi + 1);
  return (a + (b - a) * xf) * (1 - yf) + (c + (d - c) * xf) * yf;
}
function fbm(x, y) { return vnoise(x, y) * 0.62 + vnoise(x * 2.03 + 11.2, y * 2.03 - 4.1) * 0.26 + vnoise(x * 4.1 - 7.3, y * 4.1 + 2.7) * 0.12; }

const BW = Math.max(360, Math.min(680, Math.round(width / 2.5)));
const BH = Math.max(120, Math.round(BW * height / width));
if (!S.g || S.bw !== BW || S.bh !== BH) { S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.bw = BW; S.bh = BH; }

// continuous ping-pong scan through the volume (never re-phases)
const drift = 0.55 * Math.sin(K.t * 0.037) + 0.30 * Math.sin(K.t * 0.091 + 1.3);
let zt = (K.t * 0.028 * (0.4 + P.speed) + drift * 0.2) % 2; if (zt < 0) zt += 2;
const z = zt < 1 ? zt : 2 - zt;               // 0..1..0 sweep
const zc = 0.5 + (z - 0.5) * 0.86;            // keep off the very poles
const prof = Math.pow(Math.max(0, Math.sin(Math.PI * zc)), 0.55);   // head size vs depth
const vent = Math.max(0, Math.sin(Math.PI * (zc - 0.06)) * 1.15 - 0.42); // ventricles only mid-volume

const style = P.style;
const mag = Math.max(1, P.scale);
const asp = BW / BH;
const rx = (0.30 + 0.055 * prof) * (asp > 1 ? 1 : asp);
const ry = (0.36 + 0.05 * prof) / (asp > 1 ? 1 : 1);
const csfPulse = 0.5 + 0.5 * Math.sin(K.t * 1.7 + 0.6) + A.lowmid * 0.5;
