    let ny = (j / BH - 0.5) / mag - (P.y - 0.5) * (1 - 1 / mag);
    nx *= asp;                                  // isotropic
    const ang = Math.atan2(ny, nx);
    const warp = (fbm(nx * 7 + z * 3.1, ny * 7 - z * 2.2) - 0.5);
    const rr = Math.sqrt((nx / rx) * (nx / rx) + (ny / ry) * (ny / ry)) + warp * 0.05;
    // gyral ribboning at the cortical rim
    const gyr = fbm(Math.cos(ang) * 5.5 + nx * 3, Math.sin(ang) * 5.5 + ny * 3 + z * 4);

    let sig = 0;      // MR signal 0..1 for this tissue in the current window
    let act = 0;      // BOLD activation (fMRI style)
    if (rr > 1.02) {
      sig = noiseFloor + hh(i * 3 + (z * 90 | 0), j * 3) * 0.03;    // air / background
    } else if (rr > 0.965) {                    // scalp + subcutaneous fat
      sig = style === 'T2' ? 0.6 : 0.82;
    } else if (rr > 0.9) {                       // cortical bone (dark on MR)
      sig = 0.09 + fbm(nx * 20, ny * 20) * 0.05;
    } else if (rr > 0.86) {                      // subarachnoid CSF moat
      sig = style === 'T2' ? 0.92 : (style === 'FLAIR' ? 0.14 : 0.13);
      sig *= 0.6 + 0.4 * csfPulse;
    } else {
