      const depth = (0.86 - rr) / 0.86;          // 0 at cortex .. 1 at centre
      const fold = 0.5 + 0.5 * Math.sin(gyr * 6.2 + depth * 9);
      const isGrey = depth < 0.12 + fold * 0.08 * thick;
      const grey = style === 'T2' ? 0.5 : 0.48;
      const white = style === 'T2' ? 0.4 : 0.72;
      sig = isGrey ? grey : white;
      sig += (fbm(nx * 14 + 3, ny * 14 - z) - 0.5) * 0.08;         // parenchymal texture
      // lateral ventricles: two paramedian pockets, CSF signal
      const vx = Math.abs(nx) - 0.045 * prof, vy = ny + 0.02;
      const vd = Math.sqrt((vx / (0.075 * vent + 0.001)) * (vx / (0.075 * vent + 0.001)) + (vy / (0.11 * vent + 0.001)) * (vy / (0.11 * vent + 0.001)));
      if (vent > 0.05 && vd < 1 && Math.abs(nx) > 0.012) {
        sig = style === 'T2' ? 0.95 : (style === 'FLAIR' ? 0.1 : 0.1);
        sig *= 0.65 + 0.35 * csfPulse;
      }
      // FLAIR hyperintensities / lesions
      if (style === 'FLAIR') {
        const les = fbm(nx * 9 + 40 + (z * 20 | 0) * 0.11, ny * 9 - 12);
        if (les > 0.82 && depth > 0.15) sig = Math.max(sig, 0.6 + (les - 0.82) * 3.5);
      }
      // BOLD activation clusters
      const av = fbm(nx * 6 + z * 5 + 7, ny * 6 - z * 3) ;
      act = Math.max(0, av - 0.62) * (0.5 + 0.5 * Math.sin(K.t * 0.9 + depth * 4)) * (depth < 0.5 ? 1 : 0.3);
    }

    // Rician-ish MR noise grain
    const nz = (fbm(i * 0.5 + (z * 300 | 0) * 0.13, j * 0.5) - 0.5) * 0.12 * gr;
    let v = Math.max(0, Math.min(1, sig * gain + nz));
    // coil-sensitivity vignette (bright centre, gentle falloff)
    const vg = 1 - 0.28 * (rr > 1 ? 1 : rr) * (rr > 1 ? 1 : rr);
    v *= vg;

    let r, gg, b;
    if (style === 'BOLD') {
      const base = v * 0.62;                     // grey anatomical underlay
      const a2 = Math.min(1, act * (1.2 + P.energy));
