      r = base + a2 * (0.9);
      gg = base + a2 * (a2 < 0.5 ? a2 * 1.4 : (1 - a2) * 1.4);
      b = base * 1.05 + Math.max(0, 0.4 - act * 2) * 0.12;
    } else {
      // faint clinical tint on the greyscale
      r = v * (0.97 + Math.cos(tint * 6.283) * 0.03);
      gg = v * (0.99);
      b = v * (0.99 + Math.sin(tint * 6.283) * 0.05);
    }
    const o = 4 * (j * BW + i);
    px[o] = Math.max(0, Math.min(255, r * 255));
    px[o + 1] = Math.max(0, Math.min(255, gg * 255));
    px[o + 2] = Math.max(0, Math.min(255, b * 255));
    px[o + 3] = 255;
  }
}
